package org.jsoup.helper;

import org.jsoup.Connection;
import org.junit.Test;
import java.net.MalformedURLException;
import java.net.URL;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import static org.junit.Assert.assertEquals;

public class UrlBuilderTest {

    @Test
    public void urlBuilderConstructorTest() throws MalformedURLException {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://www.google.com"));
        assertNotNull(urlBuilder);
    }

    @Test
    public void buildValidURLTest() throws MalformedURLException {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://www.google.com"));
        URL outputUrl = urlBuilder.build();
        assertEquals("http://www.google.com", outputUrl.toString());
    }

    @Test(expected = MalformedURLException.class)
    public void buildInvalidURLTest() throws MalformedURLException {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http:/google.com"));
        urlBuilder.build();
    }

    @Test
    public void appendKeyValURLTest() throws Exception {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://www.google.com"));
        urlBuilder.appendKeyVal(new Connection.KeyVal("key", "value"));
        URL outputUrl = urlBuilder.build();
        assertEquals("http://www.google.com?key=value", outputUrl.toString());
    }

    @Test
    public void appendMultipleKeyValURLTest() throws Exception {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("http://www.google.com"));
        urlBuilder.appendKeyVal(new Connection.KeyVal("key1", "value"));
        urlBuilder.appendKeyVal(new Connection.KeyVal("key2", "value"));
        URL outputUrl = urlBuilder.build();
        assertEquals("http://www.google.com?key1=value&key2=value", URLDecoder.decode(outputUrl.toString(), StandardCharsets.UTF_8.toString()));
    }
}
```
